import { useState } from 'react';
import { t } from '@/i18n/index.js';
import { Sheet } from './Sheet.js';
import styles from './NoteSheet.module.css';

interface NoteSheetProps {
  initial: string;
  headword: string;
  onSave: (memo: string) => void;
  onClose: () => void;
}

/**
 * The note editor, as the prototype draws it: a kicker over the word, four
 * lines to write in, Cancel beside a wider Save. The same sheet serves the
 * session and the word detail, so a note feels the same wherever it is made.
 */
export function NoteSheet({ initial, headword, onSave, onClose }: NoteSheetProps): React.JSX.Element {
  const [value, setValue] = useState(initial);
  return (
    <Sheet onClose={onClose}>
      <div className={styles.head}>
        <span className={styles.kicker}>{t('note.for')}</span>
        <span className={styles.word}>{headword}</span>
      </div>
      <textarea
        className={styles.textarea}
        value={value}
        rows={4}
        dir="auto"
        autoFocus
        placeholder={t('note.placeholder')}
        aria-label={t('word.myNote')}
        onChange={(event) => {
          setValue(event.target.value);
        }}
      />
      <div className={styles.actions}>
        <button type="button" className={styles.cancel} onClick={onClose}>
          {t('action.cancel')}
        </button>
        <button
          type="button"
          className={styles.save}
          onClick={() => {
            onSave(value.trim());
          }}
        >
          {t('note.save')}
        </button>
      </div>
    </Sheet>
  );
}
