import { NavigationType, useNavigate, useNavigationType, useParams } from 'react-router-dom';
import { dayIndex, firstMeaning, ttsLocaleOf, type LanguageCode, type Word } from '@lexpad/core';
import { Bilingual } from '@/components/ui/Bilingual.js';
import { BoxMeter } from '@/components/ui/BoxMeter.js';
import { Confirm } from '@/components/ui/Confirm.js';
import { Toast } from '@/components/ui/Toast.js';
import { Icon } from '@/components/ui/Icon.js';
import { usePane } from '@/components/layout/pane.js';
import { NoteSheet } from '@/components/ui/NoteSheet.js';
import { Sheet } from '@/components/ui/Sheet.js';
import { Skeleton } from '@/components/ui/Skeleton.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { localTimeZone } from '@/lib/format.js';
import { platform } from '@/lib/platform/index.js';
import { useCanSpeak } from '@/lib/useCanSpeak.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { getWord, listNotebooks, listWords } from '@/db/repo.js';
import {
  applyCorrection,
  dismissCorrection,
  enrichWord,
  moveMeaning,
  removeWord,
  setProgressFlags,
  raiseWord,
  restoreWordOrder,
} from '@/db/mutations.js';
import { generateCard } from '@/features/ai/generate.js';
import { isRefusal } from '@/features/ai/quota.js';
import { ProOffer } from '@/features/billing/ProOffer.js';
import { Refine } from '@/features/ai/Refine.js';
import { syncSoon } from '@/sync/store.js';
import { AddSheet } from '@/features/notebook/AddSheet.js';
import { RETURN_TO_PLACE } from '@/features/notebook/placeMemory.js';
import styles from './WordDetail.module.css';

interface DetailData {
  word: Word | undefined;
  targetLang: LanguageCode;
  meaningLang: LanguageCode;
  /** The notebook words this one links to, with their first meaning. */
  related: { id: string; headword: string; meaning: string }[];
  today: number;
}

const EMPTY: DetailData = {
  word: undefined,
  targetLang: 'en',
  meaningLang: 'fa',
  related: [],
  today: 0,
};

async function loadDetail(wordId: string): Promise<DetailData> {
  /*
   * The word's own notebook decides its languages, not whichever notebook
   * happens to be active. With every notebook in view you can open an
   * English word while a Turkish notebook is active, and this screen used
   * to hand the speaker the active notebook's language -- so it read the
   * English word aloud in Turkish, and laid the meaning out in the wrong
   * direction when the two scripts disagreed.
   */
  const [word, notebooks] = await Promise.all([getWord(wordId), listNotebooks()]);
  if (!word) return EMPTY;
  const notebook = notebooks.find((one) => one.id === word.notebookId);
  const ids = word.relatedWordIds ?? [];
  const related =
    ids.length === 0
      ? []
      : (await listWords(word.notebookId))
          .filter((candidate) => ids.includes(candidate.id))
          .map((candidate) => ({
            id: candidate.id,
            headword: candidate.headword,
            meaning: firstMeaning(candidate),
          }));
  return {
    word,
    targetLang: notebook?.targetLang ?? 'en',
    meaningLang: notebook?.meaningLang ?? 'fa',
    related,
    today: dayIndex(new Date(), localTimeZone()),
  };
}

/**
 * Everything known about one word, and the actions that apply to it:
 * practise it, practise its group, star it, note it, retire it or remove it.
 */
interface WordDetailProps {
  /** The word to show; read from the route when absent. */
  wordId?: string | undefined;
  /**
   * Inside a sheet over another screen, say a running session: the back
   * arrow closes the sheet, and the actions that would leave the screen
   * (practise, retire, remove) are not offered.
   */
  embedded?: boolean | undefined;
  onClose?: (() => void) | undefined;
}

export function WordDetail({
  wordId: givenId,
  embedded = false,
  onClose,
}: WordDetailProps = {}): React.JSX.Element {
  const params = useParams();
  const wordId = givenId ?? params.wordId ?? '';
  const navigate = useNavigate();
  const data = useLiveQuery(() => loadDetail(wordId), EMPTY, [wordId]);
  const canSpeak = useCanSpeak(data.targetLang);
  const [noteOpen, setNoteOpen] = useState(false);
  const [editOpen, setEditOpen] = useState(false);
  const [confirmRemove, setConfirmRemove] = useState(false);
  const [moreOpen, setMoreOpen] = useState(false);
  const [toast, setToast] = useState<{ message: string; undo: () => void } | undefined>();
  const [notice, setNotice] = useState<string | undefined>(undefined);
  const [improving, setImproving] = useState(false);
  const [improved, setImproved] = useState<string | undefined>(undefined);
  /**
   * Whether the last attempt was refused for the day rather than failing.
   * The two deserve different words: nothing went wrong when an allowance
   * runs out, and calling it a failure sends people looking for a fault
   * that is not there.
   */
  const [restingHere, setRestingHere] = useState(false);
  const timeZone = useMemo(() => localTimeZone(), []);
  const { word } = data;
  // Opened beside the notebook on an expanded window, where the split view
  // owns the page's <main>.
  const pane = usePane();
  const Root = pane === undefined ? 'main' : 'div';

  // A word opened from far down the notebook starts at its own top; a step
  // back or forward to it keeps where it was. Beside the list the pane
  // scrolls on its own and the window belongs to the list.
  const navigationType = useNavigationType();
  useEffect(() => {
    if (pane === undefined && !embedded && navigationType !== NavigationType.Pop) window.scrollTo(0, 0);
  }, [wordId, pane, embedded, navigationType]);

  if (word === undefined) {
    return (
      <Root className={styles.screen}>
        {/* The shape of the word screen rather than a spinner in the middle
            of nothing, and silent for the first fraction of a second so a
            read that lands at once never flashes a placeholder. */}
        <Skeleton lines={4} />
        <span className="sr-only" role="status">
          {t('state.loading')}
        </span>
      </Root>
    );
  }

  const progress = word.progress;
  const starred = progress?.starred === true;
  const retired = progress?.retired === true;
  const speak = (text: string, lang: LanguageCode): void => {
    platform.tts.speak(text, ttsLocaleOf(lang));
  };

  /**
   * Asks the model for the full card and pours in what this entry lacks.
   * The learner's own text, note and learning state are never touched.
   */
  const improve = async (hint?: string): Promise<void> => {
    if (improving) return;
    setImproving(true);
    setImproved(undefined);
    try {
      const card = await generateCard(word.notebookId, word.headword, hint === undefined ? {} : { hint });
      const added = await enrichWord(word.id, card);
      void syncSoon();
      setRestingHere(false);
      setImproved(added === 0 ? t('word.improveNothing') : t('word.improved', { count: added }));
    } catch (cause) {
      const refused = isRefusal(cause);
      setRestingHere(refused);
      setImproved(refused ? t('ai.resting') : t('word.improveFailed'));
    } finally {
      setImproving(false);
    }
  };

  const dueLabel = (): string => {
    if (progress === undefined) return t('word.notStarted');
    const days = progress.dueDay - data.today;
    if (days <= 0) return t('word.dueToday');
    if (days === 1) return t('word.dueTomorrow');
    return t('word.dueIn', { days });
  };

  const meanings = word.meanings ?? [];
  const expressions = word.expressions ?? [];
  const collocations = word.collocations ?? [];
  const freeRelatives = word.relatedWords ?? [];
  const memo = progress?.memo ?? '';

  return (
    <Root className={cx(styles.screen, embedded && styles.embedded)}>
      <div className={styles.topBar}>
        <button
          type="button"
          className={styles.back}
          aria-label={embedded ? t('action.close') : t('action.back')}
          onClick={() => {
            if (embedded) onClose?.();
            else void navigate(-1);
          }}
        >
          <Icon name="chevronLeft" size={20} weight={2} />
        </button>
        <div className={styles.topRight}>
          <span className={styles.source}>{sourceLabel(word.source)}</span>
          <button
            type="button"
            className={styles.back}
            aria-label={t('word.edit')}
            onClick={() => {
              setEditOpen(true);
            }}
          >
            <Icon name="pencil" size={18} weight={2} />
          </button>
          <button
            type="button"
            className={styles.back}
            aria-label={t('word.moreTitle')}
            onClick={() => {
              setMoreOpen(true);
            }}
          >
            <Icon name="more" size={18} weight={2} />
          </button>
        </div>
      </div>

      <div className={styles.head}>
        <div className={styles.headRow}>
          <div className={styles.headText}>
            <h1 className={styles.headword}>
              <Bilingual lang={data.targetLang}>{word.headword}</Bilingual>
            </h1>
            <div className={styles.meta}>
              {[word.pronunciation, word.pos].filter((part) => part !== undefined && part !== '').join(' · ')}
            </div>
          </div>
          <button
            type="button"
            className={cx(styles.star, starred && styles.starOn)}
            aria-label={starred ? t('action.unstar') : t('action.star')}
            aria-pressed={starred}
            onClick={() => {
              void setProgressFlags(word.id, { starred: !starred }, timeZone).then(() => syncSoon());
            }}
          >
            <Icon name={starred ? 'starOn' : 'star'} size={21} />
          </button>
          {canSpeak && (
            <button
              type="button"
              className={styles.speak}
              aria-label={t('action.speak')}
              onClick={() => {
                speak(word.headword, data.targetLang);
              }}
            >
              <Icon name="speaker" size={20} weight={1.9} />
            </button>
          )}
        </div>

        <div className={styles.tags}>
          {progress !== undefined && <BoxMeter box={progress.box} label className={styles.boxTag} />}
          <span className={styles.tag}>{dueLabel()}</span>
          {word.level !== undefined && <span className={styles.tag}>{word.level}</span>}
          <span className={cx(styles.tag, styles.tagTopic)}>{word.category}</span>
          {retired && <span className={cx(styles.tag, styles.tagBad)}>{t('notebook.retired')}</span>}
        </div>
      </div>

      {word.correction !== undefined && word.correction !== '' && word.originalMeaning !== undefined && (
        // An imported correction of the meaning: the old text struck through,
        // the corrected one below, as the prototype shows it.
        <div className={styles.correction}>
          <div className={styles.correctionLabel}>{t('word.correctionBlock')}</div>
          <div className={styles.correctionOriginal}>
            <Bilingual lang={data.meaningLang}>{word.originalMeaning}</Bilingual>
          </div>
          <div className={styles.correctionText}>
            <Bilingual lang={data.meaningLang}>{word.correction}</Bilingual>
          </div>
        </div>
      )}
      {word.correction !== undefined && word.correction !== '' && word.originalMeaning === undefined && (
        // The model's corrected form of a headword the learner typed. Say
        // what it is and offer the two things one can do about it.
        <div className={styles.correction}>
          <div className={styles.correctionLabel}>{t('word.correctForm')}</div>
          <p className={styles.correctionExplain}>
            {t('word.correctionExplain', { typed: word.headword, correct: word.correction })}
          </p>
          <div className={styles.correctionActions}>
            <button
              type="button"
              className={styles.correctionButton}
              onClick={() => {
                const correct = word.correction ?? '';
                void applyCorrection(word.id).then((outcome) => {
                  if (outcome === 'taken') setNotice(t('word.correctionTaken', { correct }));
                  else void syncSoon();
                });
              }}
            >
              {t('word.useCorrection', { correct: word.correction })}
            </button>
            <button
              type="button"
              className={cx(styles.correctionButton, styles.correctionQuiet)}
              onClick={() => {
                void dismissCorrection(word.id).then(() => syncSoon());
              }}
            >
              {t('word.keepMine')}
            </button>
          </div>
          {notice !== undefined && (
            <p className={styles.correctionNotice} role="status">
              {notice}
            </p>
          )}
        </div>
      )}

      <div className={styles.senses}>
        {meanings.map((meaning, index) => (
          <div key={`${meaning.meaning}-${String(index)}`} className={styles.sense}>
            <div className={styles.senseHead}>
              {meanings.length > 1 && <span className={styles.senseNumber}>{index + 1}</span>}
              <span className={styles.meaning}>
                <Bilingual lang={data.meaningLang}>{meaning.meaning}</Bilingual>
              </span>
              {/* The first meaning is the one practice asks about, and it is
                  often not the sense somebody saved the word for. Moving one
                  up acts at once and offers Undo: it is order, not loss. */}
              {index > 0 && (
                <button
                  type="button"
                  className={styles.senseUp}
                  aria-label={t('word.meaningUp', { n: index + 1 })}
                  onClick={() => {
                    void moveMeaning(word.id, index, index - 1).then((moved) => {
                      if (!moved) return;
                      void syncSoon();
                      setToast({
                        message: index === 1 ? t('word.meaningFirstToast') : t('word.meaningMovedToast'),
                        undo: () => {
                          void moveMeaning(word.id, index - 1, index).then(() => syncSoon());
                        },
                      });
                    });
                  }}
                >
                  <Icon name="chevronUp" size={16} weight={2} />
                </button>
              )}
            </div>
            {meaning.gloss !== undefined && meaning.gloss !== '' && (
              <div className={styles.gloss}>
                <Bilingual lang={data.targetLang}>{meaning.gloss}</Bilingual>
              </div>
            )}
            {(meaning.examples ?? []).map((example, position) => (
              <div key={`${example.sentence}-${String(position)}`} className={styles.example}>
                <div className={styles.exampleRow}>
                  <span className={styles.exampleText}>
                    <Bilingual lang={data.targetLang}>{example.sentence}</Bilingual>
                  </span>
                  {canSpeak && (
                    <button
                      type="button"
                      className={styles.exampleSpeak}
                      aria-label={t('action.speak')}
                      onClick={() => {
                        speak(example.sentence, data.targetLang);
                      }}
                    >
                      <Icon name="speaker" size={16} weight={1.9} />
                    </button>
                  )}
                </div>
                {example.translation !== undefined && (
                  <div className={styles.exampleTranslation}>
                    <Bilingual lang={data.meaningLang}>{example.translation}</Bilingual>
                  </div>
                )}
              </div>
            ))}
          </div>
        ))}
      </div>

      {expressions.length > 0 && (
        <section className={styles.section}>
          <h2 className={styles.sectionTitle}>{t('word.expressions')}</h2>
          <div className={styles.group}>
            {expressions.map((phrase) => (
              <div key={phrase.text} className={styles.expression}>
                <span className={styles.expressionText}>
                  <Bilingual lang={data.targetLang}>{phrase.text}</Bilingual>
                </span>
                {phrase.translation !== undefined && (
                  <span className={styles.expressionTranslation}>
                    <Bilingual lang={data.meaningLang}>{phrase.translation}</Bilingual>
                  </span>
                )}
              </div>
            ))}
          </div>
        </section>
      )}

      {collocations.length > 0 && (
        <section className={styles.section}>
          <h2 className={styles.sectionTitle}>{t('word.collocations')}</h2>
          <div className={styles.collocations}>
            {collocations.map((phrase) => (
              <span key={phrase} className={styles.collocation}>
                {phrase}
              </span>
            ))}
          </div>
        </section>
      )}

      <section className={styles.section}>
        <div className={styles.sectionHead}>
          <h2 className={styles.sectionTitle}>{t('word.myNote')}</h2>
          <button
            type="button"
            className={styles.sectionAction}
            onClick={() => {
              setNoteOpen(true);
            }}
          >
            {memo === '' ? t('word.addNote') : t('word.editNote')}
          </button>
        </div>
        {memo !== '' && (
          <p className={styles.memo} dir="auto">
            {memo}
          </p>
        )}
      </section>

      {word.usageNote !== undefined && word.usageNote !== '' && (
        <section className={styles.section}>
          <h2 className={styles.sectionTitle}>{t('word.usageNote')}</h2>
          <p className={styles.usage}>
            <Bilingual lang={data.meaningLang}>{word.usageNote}</Bilingual>
          </p>
        </section>
      )}

      {data.related.length > 0 && (
        <section className={styles.section}>
          <h2 className={styles.sectionTitle}>{t('word.relatedInNotebook')}</h2>
          {word.relatedNote !== undefined && word.relatedNote !== '' && (
            <p className={styles.relatedNote}>
              <Bilingual lang={data.meaningLang}>{word.relatedNote}</Bilingual>
            </p>
          )}
          <div className={styles.group}>
            {data.related.map((other) => (
              <button
                key={other.id}
                type="button"
                className={styles.related}
                onClick={() => {
                  void navigate(`/words/${other.id}`);
                }}
              >
                <span className={styles.relatedWord}>
                  <Bilingual lang={data.targetLang}>{other.headword}</Bilingual>
                </span>
                <span className={styles.relatedRight}>
                  <span className={styles.relatedMeaning}>
                    <Bilingual lang={data.meaningLang}>{other.meaning}</Bilingual>
                  </span>
                  <Icon name="chevronRight" size={16} weight={2} className={styles.chevron} />
                </span>
              </button>
            ))}
          </div>
        </section>
      )}

      {freeRelatives.length > 0 && (
        <section className={styles.section}>
          <h2 className={styles.sectionTitle}>{t('word.relatedWords')}</h2>
          <div className={styles.group}>
            {freeRelatives.map((phrase) => (
              <div key={phrase.text} className={styles.freeRow}>
                <span className={styles.freeWord}>
                  <Bilingual lang={data.targetLang}>{phrase.text}</Bilingual>
                </span>
                {phrase.translation !== undefined && (
                  <span className={styles.freeMeaning}>
                    <Bilingual lang={data.meaningLang}>{phrase.translation}</Bilingual>
                  </span>
                )}
                {canSpeak && (
                  <button
                    type="button"
                    className={styles.freeSpeak}
                    aria-label={t('action.speak')}
                    onClick={() => {
                      speak(phrase.text, data.targetLang);
                    }}
                  >
                    <Icon name="speaker" size={16} weight={1.9} />
                  </button>
                )}
              </div>
            ))}
          </div>
        </section>
      )}

      {!embedded && (
        <div className={styles.actions}>
          {/* A session over named words is the group deck, which takes the
              ids in the address -- the same shape the notebook's "Practise
              these" uses. There is no "word" deck and there never was: this
              asked for one and quietly got the daily deck instead, so the
              button practised everything due rather than this word.

              Not offered for a retired word. Every deck leaves retired
              words out, so the button would open a session with nothing in
              it -- and a word somebody has set aside is not one to be
              asked about. Unretiring it brings both buttons back. */}
          {!retired && (
            <button
              type="button"
              className={styles.primary}
              onClick={() => {
                void navigate(`/session?deck=group&ids=${word.id}`);
              }}
            >
              {t('word.practiseNow')}
            </button>
          )}
          {!retired && data.related.length > 0 && (
            <button
              type="button"
              className={styles.secondary}
              onClick={() => {
                // The word and its relatives: a group somebody is learning
                // together is only a group with the word in it.
                const ids = [word.id, ...data.related.map((other) => other.id)];
                void navigate(`/session?deck=group&ids=${ids.join(',')}`);
              }}
            >
              {t('word.practiseGroup')}
            </button>
          )}
          <button
            type="button"
            className={styles.secondary}
            disabled={improving}
            onClick={() => {
              void improve();
            }}
          >
            {improving ? (
              <span className={styles.spinner} aria-hidden="true" />
            ) : (
              <Icon name="sparkles" size={16} weight={2} />
            )}
            {improving ? t('word.improving') : t('word.improve')}
          </button>
          {improved !== undefined && (
            <p className={styles.improved} role="status">
              {improved}
            </p>
          )}
          {/* Refused for today, not broken. The offer belongs here because
              this is the moment somebody wanted more and was told no. */}
          {restingHere && <ProOffer occasion="resting" subtle />}
          {improved !== undefined && !improving && !restingHere && (
            <Refine
              onRefine={(hint) => {
                void improve(hint);
              }}
            />
          )}
        </div>
      )}

      {moreOpen && (
        <Sheet
          title={t('word.moreTitle')}
          onClose={() => {
            setMoreOpen(false);
          }}
        >
          <div className={styles.moreList}>
            <button
              type="button"
              className={styles.quiet}
              onClick={() => {
                // Moving is a matter of order, not of loss, so it acts at once
                // and Undo puts the word back where it was.
                void raiseWord(word.id).then((before) => {
                  void syncSoon();
                  setToast({
                    message: t('word.movedToast'),
                    undo: () => {
                      if (before) void restoreWordOrder(word.id, before).then(() => syncSoon());
                    },
                  });
                });
              }}
            >
              {t('word.moveToTop')}
            </button>
            <button
              type="button"
              className={styles.quiet}
              onClick={() => {
                // Retiring acts at once and offers Undo, like a grade in the
                // session; it is a setting, not a loss.
                const next = !retired;
                void setProgressFlags(word.id, { retired: next }, timeZone).then(() => {
                  void syncSoon();
                  setToast({
                    message: next ? t('word.retiredToast') : t('word.unretiredToast'),
                    undo: () => {
                      void setProgressFlags(word.id, { retired: !next }, timeZone).then(() => syncSoon());
                    },
                  });
                });
              }}
            >
              {retired ? t('word.unretire') : t('word.retire')}
            </button>
            <button
              type="button"
              className={cx(styles.quiet, styles.danger)}
              onClick={() => {
                setConfirmRemove(true);
              }}
            >
              {t('word.remove')}
            </button>
          </div>
        </Sheet>
      )}
      {confirmRemove && (
        <Confirm
          title={t('word.removeTitle', { word: word.headword })}
          body={t('word.removeBody')}
          confirmLabel={t('word.remove')}
          danger
          onCancel={() => {
            setConfirmRemove(false);
          }}
          onConfirm={() => {
            setConfirmRemove(false);
            void removeWord(word.id).then(() => {
              void syncSoon();
              // Back to the list where the reader left it (placeMemory.ts).
              void navigate('/notebook', { replace: true, state: RETURN_TO_PLACE });
            });
          }}
        />
      )}

      {toast !== undefined && (
        <Toast
          message={toast.message}
          onUndo={toast.undo}
          onDone={() => {
            setToast(undefined);
          }}
        />
      )}

      {editOpen && (
        <AddSheet
          edit={word}
          notebookId={word.notebookId}
          targetLang={data.targetLang}
          meaningLang={data.meaningLang}
          onClose={() => {
            setEditOpen(false);
          }}
        />
      )}

      {noteOpen && (
        <NoteSheet
          initial={progress?.memo ?? ''}
          headword={word.headword}
          onSave={(memo) => {
            void setProgressFlags(word.id, { memo }, timeZone).then(() => syncSoon());
            setNoteOpen(false);
          }}
          onClose={() => {
            setNoteOpen(false);
          }}
        />
      )}
    </Root>
  );
}

/** Where the entry came from, in the prototype's own words. */
function sourceLabel(source: Word['source']): string {
  const labels: Record<Word['source'], string> = {
    manual: t('word.sourceManual'),
    ai: t('word.sourceAi'),
    assistant: t('word.sourceAssistant'),
    import: t('word.sourceImport'),
    shared: t('word.sourceShared'),
  };
  return labels[source];
}
